solutions.javascript:
function countBits(n) {
    const ans = Array(n + 1).fill(0);
    for (let i = 0; i <= n; ++i) {
        ans[i] = bitCount(i);
    }
    return ans;
}
function bitCount(n) {
    let count = 0;
    while (n) {
        n &= n - 1;
        ++count;
    }
    return count;
}

